import { GetToken, judgeButtonPermission, RemoveToken, SetToken } from '@/utils/utils';
    // ...
const user = {
  namespaced: true,
  state: {
    token: GetToken('token'),
    name: '',
    avatar: '',
    roles: null,
    webSocket: null,
    userInfor: {},
    permissions: null
  },
  mutations: {
    RESET_STATE: (state) => {
      Object.assign(state, {
        token: GetToken('token'),
        name: '',
        avatar: '',
        infor: {},
        roles: null,
        webSocket: null,
        userInfor: {},
        permissions: null
      });
    },
    SET_PREMISSIONS: (state, permissions) => {
      state.permissions = permissions;
    },
    SET_TOKEN: (state, token) => {
      state.token = token;
      SetToken('token', token);
    },
    SET_NAME: (state, name) => {
      state.name = name;
    },
    SET_AVATAR: (state, avatar) => {
      state.avatar = avatar;
    },

    SET_ROLES: (state, roles) => {
      state.roles = roles;
    },
    SET_USER_INFOR: (state, userInfor) => {
      state.userInfor = userInfor;
    }
  },
  actions: {

    // get user info
    async getInfo({ commit, state }) {
      return new Promise(async (resolve, reject) => {
        try {
          const res = await GetAccountInfo().catch(() => {
            reject();
          });
          if (res) {
            const { sysAccount, permissions } = res;
            const { accountname, avatar } = sysAccount;
            commit('SET_AVATAR', avatar);
            commit('SET_NAME', accountname);
            commit('SET_USER_INFOR', sysAccount);
            commit('SET_ROLES', res.roles);
            commit('SET_PREMISSIONS', permissions);
            resolve();
          }
        } catch (error) {
        }
      });
    },

    // user logout
    logout({ commit }) {
      RemoveToken('token');
      commit('RESET_STATE');
      window.location.href = `http://${process.env.VUE_APP_AUTH_URL}?from=${process.env.VUE_APP_SYSTEM_URL}`;
    },

    jumpNoPermission({ commit }) {
      RemoveToken('token');
      commit('RESET_STATE');
      router.push({ name: '404' });

    },


    // 保存账户权限
    saveAccountAuth({ commit, state }, params) {
      const data = {
        ...params,
        accountId: state.userInfor.accountId
      };
      return new Promise((resolve, reject) => {
        SaveAccountAuth(data)
          .then((res) => {
            resolve();
          })
          .catch(() => {
            reject();
          });
      });
    },

    // 判断按钮权限
    judgeButtonPermission({ state }, params) {
      return new Promise((resolve, reject) => {
        const { permissions } = state;
        let flag = judgeButtonPermission(permissions, params);
        resolve(flag);
      });
    }
  }
};

